const departure = $json.body.departure_date;
const returnDate = $json.body.return_date;
const origin = $json.body.origin;
const destination = $json.body.destination;
const passengers = $json.body.passengers || 1;

function addDays(dateStr, days) {
  const d = new Date(dateStr);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

const offsets = [-2, -1, 0, 1, 2];
const combinations = [];

for (const depOffset of offsets) {
  const newDep = addDays(departure, depOffset);
  if (returnDate) {
    for (const retOffset of offsets) {
      const newRet = addDays(returnDate, retOffset);
      if (new Date(newRet) > new Date(newDep)) {
        combinations.push({
          origin,
          destination,
          departure_date: newDep,
          return_date: newRet,
          passengers: parseInt(passengers),
          original_departure: departure,
          original_return: returnDate
        });
      }
    }
  } else {
    combinations.push({
      origin,
      destination,
      departure_date: newDep,
      return_date: null,
      passengers: parseInt(passengers),
      original_departure: departure,
      original_return: null
    });
  }
}

return combinations.map(c => ({ json: c }));

const offerRequestId = $json.data?.id;
const departureDate = $('Generate Date Range').item.json.departure_date;
const returnDate = $('Generate Date Range').item.json.return_date;
const origin = $('Generate Date Range').item.json.origin;
const destination = $('Generate Date Range').item.json.destination;
const passengers = $('Generate Date Range').item.json.passengers;

if (!offerRequestId) {
  throw new Error('No offer_request_id returned from Duffel');
}

return [{
  json: {
    offer_request_id: offerRequestId,
    departure_date: departureDate,
    return_date: returnDate,
    origin,
    destination,
    passengers
  }
}];

const offerData = $json.data?.[0];
const requestMeta = $('Extract Offer Request ID').item.json;

if (!offerData) {
  return [{
    json: {
      departure_date: requestMeta.departure_date,
      return_date: requestMeta.return_date,
      origin: requestMeta.origin,
      destination: requestMeta.destination,
      passengers: requestMeta.passengers,
      offer_id: null,
      total_amount: null,
      total_currency: null,
      stops: null,
      airline: null,
      duration: null,
      error: 'No offers found for this date combination'
    }
  }];
}

const slice = offerData.slices?.[0];
const segment = slice?.segments?.[0];
const stops = slice?.segments?.length ? slice.segments.length - 1 : 0;
const airline = segment?.operating_carrier?.name || segment?.marketing_carrier?.name || 'Unknown';
const duration = slice?.duration || null;

const depDate = new Date(requestMeta.departure_date);
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const weekday = weekdays[depDate.getDay()];

return [{
  json: {
    departure_date: requestMeta.departure_date,
    return_date: requestMeta.return_date,
    origin: requestMeta.origin,
    destination: requestMeta.destination,
    passengers: requestMeta.passengers,
    weekday,
    offer_id: offerData.id,
    total_amount: parseFloat(offerData.total_amount),
    total_currency: offerData.total_currency,
    stops,
    airline,
    duration,
    expires_at: offerData.expires_at
  }
}];

const flights = $json.all_flights || [];
const validFlights = flights.filter(f => f.total_amount !== null);

if (validFlights.length === 0) {
  return [{
    json: {
      flights_summary: 'No se encontraron vuelos disponibles para el rango de fechas solicitado.',
      raw_data: flights,
      flight_count: 0
    }
  }];
}

const summary = validFlights.map(f => 
  `Fecha: ${f.departure_date} (${f.weekday}) | ` +
  `Precio: ${f.total_amount} ${f.total_currency} | ` +
  `Escalas: ${f.stops} | ` +
  `Aerolínea: ${f.airline} | ` +
  `Duración: ${f.duration || 'N/D'}` +
  (f.return_date ? ` | Vuelta: ${f.return_date}` : '')
).join('\n');

return [{
  json: {
    flights_summary: summary,
    raw_data: validFlights,
    flight_count: validFlights.length,
    origin: validFlights[0]?.origin,
    destination: validFlights[0]?.destination
  }
}];

const aiAnalysis = $json.text || $json.response || 'Análisis no disponible';
const rawData = $('Prepare AI Prompt Data').item.json.raw_data || [];
const now = new Date();
const generatedAt = now.toLocaleString('es-AR', {
  timeZone: 'America/Argentina/Buenos_Aires',
  dateStyle: 'full',
  timeStyle: 'medium'
});

const origin = $('Prepare AI Prompt Data').item.json.origin;
const destination = $('Prepare AI Prompt Data').item.json.destination;

let reportText = `========================================\n`;
reportText += `   REPORTE DE VUELOS - ANÁLISIS IA\n`;
reportText += `========================================\n`;
reportText += `Generado: ${generatedAt}\n`;
reportText += `Ruta: ${origin} → ${destination}\n`;
reportText += `Vuelos analizados: ${rawData.length}\n`;
reportText += `\n========================================\n`;
reportText += `   ANÁLISIS DE COSTO-BENEFICIO (IA)\n`;
reportText += `========================================\n`;
reportText += aiAnalysis;
reportText += `\n\n========================================\n`;
reportText += `   DATOS CRUDOS DE VUELOS\n`;
reportText += `========================================\n`;

rawData.forEach((flight, index) => {
  reportText += `\n--- Opción ${index + 1} ---\n`;
  reportText += `Fecha salida:  ${flight.departure_date} (${flight.weekday || 'N/D'})\n`;
  if (flight.return_date) {
    reportText += `Fecha regreso: ${flight.return_date}\n`;
  }
  reportText += `Aerolínea:     ${flight.airline || 'N/D'}\n`;
  reportText += `Precio total:  ${flight.total_amount} ${flight.total_currency || ''}\n`;
  reportText += `Escalas:       ${flight.stops ?? 'N/D'}\n`;
  reportText += `Duración:      ${flight.duration || 'N/D'}\n`;
  if (flight.offer_id) {
    reportText += `Offer ID:      ${flight.offer_id}\n`;
  }
});

reportText += `\n========================================\n`;
reportText += `   FIN DEL REPORTE\n`;
reportText += `========================================\n`;

const binaryData = Buffer.from(reportText, 'utf-8').toString('base64');

return [{
  json: {
    ai_analysis: aiAnalysis,
    generated_at: generatedAt,
    flight_count: rawData.length
  },
  binary: {
    data: {
      data: binaryData,
      mimeType: 'text/plain',
      fileName: 'vuelos_reporte.txt',
      fileExtension: 'txt'
    }
  }
}];
